from pathlib import Path
import requests,json,zipfile,xml.etree.ElementTree as E,hashlib,numpy as np,cadquery as cq,re
D=Path('cvpr2027/data/web-cad-fem-more-families/deepwheel');T=Path('cvpr2027/tmp/cad-more-families-search')
r=requests.get('https://huggingface.co/api/datasets/KAIST-SmartDesignLab/DeepWheel',timeout=60);r.raise_for_status();meta=r.json();(D/'hf-source-metadata.json').write_text(json.dumps(meta,indent=2));rev=meta['sha'];files=[]
for n in ['README.md','LICENSE','readme.docx','deepwheel_sim_results.csv']:
 url=f'https://huggingface.co/datasets/KAIST-SmartDesignLab/DeepWheel/resolve/{rev}/{n}';r=requests.get(url,timeout=90);r.raise_for_status();b=r.content
 if n=='deepwheel_sim_results.csv':assert b==(D/n).read_bytes()
 (D/n).write_bytes(b);files.append(dict(file=n,url=url,sha256=hashlib.sha256(b).hexdigest(),bytes=len(b)))
(D/'hf-download-manifest.json').write_text(json.dumps(files,indent=2))
with zipfile.ZipFile(D/'readme.docx') as z:
 doc=E.fromstring(z.read('word/document.xml'));text='\n'.join(''.join(x.itertext()) for x in doc.findall('.//{http://schemas.openxmlformats.org/wordprocessingml/2006/main}p'));(T/'deepwheel-original-documentation.txt').write_text(text);print(text[:4500],flush=True)
pairs=json.loads((D/'selected-pairs.json').read_text());out=[]
for pair in pairs:
 p=D/pair['cad'];s=cq.importers.importStep(str(p)).val();bounds=s.BoundingBox();vol=s.Volume();valid=s.isValid();assert valid and len(s.Solids())==1,p.name
 mass=float(pair['result']['Mass']);massderived=vol*1e-9*2680;unitmatch=abs(massderived/mass-1);ref={k:float(v) for k,v in pair['result'].items() if k not in ['file_name','cad_member']};assert all(np.isfinite(v) and v>0 for v in ref.values())
 out.append(dict(id=pair['result']['file_name'],cad=pair['cad'],cad_geometry=dict(valid=valid,solids=len(s.Solids()),faces=len(s.Faces()),volume_mm3=vol,bounds_mm=[bounds.xmin,bounds.ymin,bounds.zmin,bounds.xmax,bounds.ymax,bounds.zmax],cad_density_mass_kg=massderived,relative_mass_difference=unitmatch,implied_density_from_published_mass_kg_m3=mass/(vol*1e-9),step_unit_declaration='millimetres'),reference=dict(mass_kg=mass,mode_7_frequency_Hz=ref['Mode7 Freq'],mode_11_frequency_Hz=ref['Mode11 Freq']),source_csv='deepwheel_sim_results.csv',source_cad_archive_member=pair['archive_member'],source_zip_crc=pair['source_zip_crc'],sha256=pair['sha256'],physics=dict(type='Free-free modal vibration',solver='Altair OptiStruct via SimLab',material='A356-T6 aluminium',young_modulus_Pa=72e9,poisson_ratio=.33,density_kg_m3=2680,reference_mesh='Tet10, average size 6 mm (publisher paper)'),provenance='Publisher synthetic wheel geometry reconstructed then converted to BREP; downloaded original unchanged',scoring_status='Candidate: scalar frequency reference available; source solver deck/mode shapes and independent mesh convergence not verified'))
 print('Audited',len(out),p.name,'faces',len(s.Faces()),'mass mismatch',unitmatch,flush=True)
cat=dict(collection='Original published DeepWheel wheel modal CAD/reference subset',source='https://dataset.narnia.ai/deepwheel.html',dataset_source='https://huggingface.co/datasets/KAIST-SmartDesignLab/DeepWheel',revision=rev,collected_date='2026-10-12',license='CC BY-NC 4.0, Soyoung Yoo and Namwoo Kang / KAIST SmartDesignLab, Narnia Labs',source_cad_reference_pairs=904,downloaded_cad_reference_pairs=10,problem_families=1,selection='Ten cases evenly spaced by sorted Mode7 frequency index; not a random or independent blind holdout',source_generated_geometry=True,local_geometry_generated=False,local_solver_runs=0,model_calls=0,certified_benchmark_admissions=0,original_dimensioned_drawing_verified=False,limitations=['Geometry is publisher-generated and mesh-reconstructed BREP, not human-authored parametric design or verified dimensioned drawing.','Modal scalar labels only: no downloaded full eigenvectors, stress fields or executable OptiStruct solver deck.','Rigid body modes precede Mode7; ordinal mode labels may swap families and need eigenvector matching for detailed modal scoring.','Publisher mesh size is 6 mm; independent mesh convergence and replay tolerances not certified.','Public labels can cause model contamination; do not claim new independent holdout.','License allows noncommercial use with attribution.','CAD mass at the stated 2680 kg/m3 density is approximately 3.25% below the published CSV mass; inferred density is approximately 2770 kg/m3, but actual solver input is not verified.'],records=out)
(D/'catalog.json').write_text(json.dumps(cat,indent=2));(D/'validation.json').write_text(json.dumps(dict(valid_single_solid_brep_cases=10,finite_positive_reference_rows=904 if len(json.loads((D/'source-result-cad-index.json').read_text()))==904 else None,exact_filename_matched_source_pairs=904,downloaded_member_crc_pass=10,full_csv_matches_pinned_publisher_mirror=True,mass_cross_checks=[dict(id=r['id'],relative_difference=r['cad_geometry']['relative_mass_difference']) for r in out],source_zip_download='Selected original archive members fetched by HTTP ranges; not full 7.6GB archive',mass_consistency_at_stated_density=False,independent_fem_replay=False,solver_runs=0,model_calls=0),indent=2))
print('DeepWheel audit complete',flush=True)
